import json
import pandas as pd

SOURCES = {
    "source_a": ("/data/source_a/users.json", "json"),
    "source_b": ("/data/source_b/users.csv", "csv"),
    "source_c": ("/data/source_c/users.parquet", "parquet"),
}

FIELD_MAP = {
    "user_id": "user_id",
    "id": "user_id",
    "userId": "user_id",
    "email": "email",
    "email_address": "email",
    "full_name": "name",
    "name": "name",
    "userName": "name",
    "registration_date": "created_date",
    "created_at": "created_date",
    "joined": "created_date",
    "status": "status",
    "is_active": "status",
    "active": "status",
}

PRIORITY = {"source_a": 0, "source_b": 1, "source_c": 2}
FIELDS = ["user_id", "name", "email", "created_date", "status"]


def normalize_status(value):
    if pd.isna(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = str(value).strip().lower()
    if text in {"true", "1", "yes", "active"}:
        return "active"
    if text in {"false", "0", "no", "inactive"}:
        return "inactive"
    return str(value).strip()


def normalize_date(value):
    if pd.isna(value):
        return None
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        return str(value).strip()
    return parsed.strftime("%Y-%m-%d")


def normalize_value(field, value):
    if field == "user_id":
        if pd.isna(value):
            return None
        return int(value)
    if field == "status":
        return normalize_status(value)
    if field == "created_date":
        return normalize_date(value)
    if pd.isna(value):
        return None
    return str(value).strip()


def load_source(path, kind):
    if kind == "json":
        df = pd.read_json(path)
    elif kind == "csv":
        df = pd.read_csv(path)
    else:
        df = pd.read_parquet(path)
    df = df.rename(columns=FIELD_MAP)
    for field in FIELDS:
        if field not in df.columns:
            df[field] = None
    df = df[FIELDS]
    for field in FIELDS:
        df[field] = df[field].map(lambda v, f=field: normalize_value(f, v))
    df = df[df["user_id"].notna()]
    return df


frames = {}
for source, (path, kind) in SOURCES.items():
    frames[source] = load_source(path, kind)

all_rows = []
for source, df in frames.items():
    for _, row in df.iterrows():
        record = row.to_dict()
        record["_source"] = source
        record["_priority"] = PRIORITY[source]
        all_rows.append(record)

combined = pd.DataFrame(all_rows)

merged_records = []
conflicts = []

for user_id, group in combined.groupby("user_id", sort=True):
    merged = {"user_id": int(user_id)}
    sources_present = set(group["_source"])

    for field in FIELDS[1:]:
        values_by_source = {}
        for _, row in group.sort_values("_priority").iterrows():
            value = row[field]
            if value is not None and not (isinstance(value, float) and pd.isna(value)):
                values_by_source.setdefault(row["_source"], value)

        if not values_by_source:
            merged[field] = None
            continue

        selected_source = min(values_by_source, key=lambda s: PRIORITY[s])
        selected_value = values_by_source[selected_source]
        merged[field] = selected_value

        distinct = {str(v) for v in values_by_source.values()}
        if len(sources_present) > 1 and len(distinct) > 1:
            conflicts.append(
                {
                    "user_id": int(user_id),
                    "field": field,
                    "values": values_by_source,
                    "selected": selected_value,
                }
            )

    merged_records.append(merged)

merged_df = pd.DataFrame(merged_records, columns=FIELDS)
merged_df = merged_df.sort_values("user_id").reset_index(drop=True)
merged_df["user_id"] = merged_df["user_id"].astype("int64")
for col in ["name", "email", "created_date", "status"]:
    merged_df[col] = merged_df[col].astype("string")

merged_df.to_parquet("/app/merged_users.parquet", index=False)

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
with open("/app/conflicts.json", "w") as f:
    json.dump(report, f, indent=2)

print(f"Merged {len(merged_df)} users with {len(conflicts)} conflicts")
